From 8dff9808e9734fb5b4eddd0a5b1472fade215490 Mon Sep 17 00:00:00 2001
From: "Andrea Parri (Microsoft)" <parri.andrea@gmail.com>
Date: Wed, 3 Feb 2021 12:35:13 +0100
Subject: [PATCH] hv_netvsc: Load and store the proper (NBL_HASH_INFO)
 per-packet info

Fix the typo.

Signed-off-by: Andrea Parri (Microsoft) <parri.andrea@gmail.com>
Fixes: 0ba35fe91ce34f ("hv_netvsc: Copy packets sent by Hyper-V out of the receive buffer")
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

diff --git a/drivers/net/hyperv/rndis_filter.c b/drivers/net/hyperv/rndis_filter.c
index 6c48a4d62736..0c2ebe7ac655 100644
--- a/drivers/net/hyperv/rndis_filter.c
+++ b/drivers/net/hyperv/rndis_filter.c
@@ -465,7 +465,7 @@ void rsc_add_data(struct netvsc_channel *nvchan,
 		}
 		nvchan->rsc.pktlen = len;
 		if (hash_info != NULL) {
-			nvchan->rsc.csum_info = *csum_info;
+			nvchan->rsc.hash_info = *hash_info;
 			nvchan->rsc.ppi_flags |= NVSC_RSC_HASH_INFO;
 		} else {
 			nvchan->rsc.ppi_flags &= ~NVSC_RSC_HASH_INFO;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by a typo in the code where the variable `hash_info` was incorrectly assigned to `nvchan->rsc.csum_info` instead of `nvchan->rsc.hash_info`. This led to the improper handling of per-packet information (NBL_HASH_INFO), which is crucial for accurate packet processing in the Hyper-V network virtual service client.

        Commit message:
        hv_netvsc: Load and store the proper (NBL_HASH_INFO)
 per-packet info

Fix the typo.

Signed-off-by: Andrea Parri (Microsoft) <parri.andrea@gmail.com>
Fixes: 0ba35fe91ce34f ("hv_netvsc: Copy packets sent by Hyper-V out of the receive buffer")
Signed-off-by: Jakub Kicinski <kuba@kernel.org>  

        Patch:

 static inline
 void rsc_add_data(struct netvsc_channel *nvchan,
 		  const struct ndis_pkt_8021q_info *vlan,
 		  const struct ndis_tcp_ip_checksum_info *csum_info,
 		  const u32 *hash_info,
 		  void *data, u32 len)
 {
 	u32 cnt = nvchan->rsc.cnt;

 	if (cnt) {
 		nvchan->rsc.pktlen += len;
 	} else {
 		/* The data/values pointed by vlan, csum_info and hash_info are shared
 		 * across the different 'fragments' of the RSC packet; store them into
 		 * the packet itself.
 		 */
 		if (vlan != NULL) {
 			memcpy(&nvchan->rsc.vlan, vlan, sizeof(*vlan));
 			nvchan->rsc.ppi_flags |= NVSC_RSC_VLAN;
 		} else {
 			nvchan->rsc.ppi_flags &= ~NVSC_RSC_VLAN;
 		}
 		if (csum_info != NULL) {
 			memcpy(&nvchan->rsc.csum_info, csum_info, sizeof(*csum_info));
 			nvchan->rsc.ppi_flags |= NVSC_RSC_CSUM_INFO;
 		} else {
 			nvchan->rsc.ppi_flags &= ~NVSC_RSC_CSUM_INFO;
 		}
 		nvchan->rsc.pktlen = len;
 		if (hash_info != NULL) {
-			nvchan->rsc.csum_info = *csum_info;
+			nvchan->rsc.hash_info = *hash_info;
 			nvchan->rsc.ppi_flags |= NVSC_RSC_HASH_INFO;
 		} else {
 			nvchan->rsc.ppi_flags &= ~NVSC_RSC_HASH_INFO;
 		}
 	}

 	nvchan->rsc.data[cnt] = data;
 	nvchan->rsc.len[cnt] = len;
 	nvchan->rsc.cnt++;
 }



